-- GENERATED by `wfj generate` from data/gossip/gossip-2e.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["2e00283f9b9bfa87"] = { "Bene. Mostri di avere la stoffa per entrare nei ranghi d'élite. Ora, altra pratica.", "." },
  ["2e00fead3721502d"] = { "Ti copro io, Guse.", "." },
  ["2e1143581cfd186e"] = { "Se una tartaruga non ha il guscio, è senzatetto o è nuda?", "." },
  ["2e168e1ce5384dcb"] = { "Ti prego, condividi con me la tua saggezza, Capoguerra.", "." },
  ["2e1c3c61278618ba"] = { "La ⟦Darkmoon Faire=Fiera di Lunacupa⟧ si trova ora nelle pianure dorate di Mulgore, appena a sud-ovest di ⟦Thunder Bluff=Picco del Tuono⟧. Non perdertela!", "." },
  ["2e1d7cf45deb85ad"] = { "Gira la chiave per avviare la macchina.", "." },
  ["2e20fb14e100235e"] = { "Il Parco è il posto giusto se cerchi addestratori di druidi. Theridan e Maldryn si trovano di solito presso il pozzo lunare al centro del quartiere.", "." },
  ["2e2f6115219c8bcd"] = { "Ora tocca a noi metterti i piedi in salamoia!", "." },
  ["2e3926033d52dd5a"] = { "Niente male. Va' a parlare con Snarl, si è appena trasferito a Orgrimmar per studiare con Saru. Cercalo nel quartiere dei guerrieri, vicino alla fucina di Saru. Ah, e ti metterà alla prova, quindi faresti meglio a essere <pronto/pronta> quanto credi di essere.", "." },
  ["2e3a1856536b9c1a"] = { "Le ⟦Burning Blade=Lame Ardenti⟧ cominciano a capire quanto siano davvero deboli. La loro magia è patetica, la loro forza misera.\n\nIl loro unico potere viene da coloro che servono, non da una vera comprensione del potere e della conoscenza.", "." },
  ["2e3b8df969732ff8"] = { "Quale professione?", "." },
  ["2e47bde63ce9542a"] = { "⟦Dire Maul=Maglio Infausto⟧", "." },
  ["2e48a472c934ee01"] = { "Intrusi! Bene, cominciavo ad annoiarmi...", "." },
  ["2e48c1a543d258f5"] = { "PROMETTO CHE STAVOLTA NON UCCIDERÒ LA TUA CIURMA. HAH! MA MIO FRATELLO POTREBBE MANGIARSELA!", "." },
  ["2e4dec109478414c"] = { "Morire oggi, su questo campo di battaglia, è morire da orco. Morire oggi è morire per i nostri piccoli. I nostri anziani. I nostri... cari.", "." },
  ["2e50dea49862cf34"] = { "Sarò felice di prenderti sotto la mia ala. Cominciamo.", "." },
  ["2e5a6accda467dba"] = { "Ugh... Hallan, non pensavo ne fossi capace...", "." },
  ["2e6098b8cf158308"] = { "UCCIDI!", "." },
  ["2e6426bd45d18e69"] = { "Ooohh... Questa pietra è bella e colorata. Vediamo se ne trovo altre così...", "." },
  ["2e6ab20bf7bf279a"] = { "Questa malattia mi annebbia la vista, ma so che devi essere un trogg. Muori, lurido invasore!", "." },
  ["2e6e6d221f0053e5"] = { "%s marcia avanti e indietro, ruggendo e facendo un gran baccano.", "." },
  ["2e71fbd78650ad8a"] = { "Vieni, {name}. Guarda cosa porta l'Incubo...", "." },
  ["2e738676019cf3ee"] = { "Ah, {race}... io conosco tante cose de 'sto mondo e come fare amuleti di gran potere.", "." },
  ["2e753256b0209e43"] = { "%s fissa lo sguardo su {name}", "." },
  ["2e8aead9a7f41512"] = { "Ugh! Stare in piedi tutto il giorno non è un modo di guadagnarsi da vivere. Avrei dovuto scegliere la sartoria.", "." },
  ["2e8b4c21030e398c"] = { "Ecco fatto, entrambe le parti hanno raccolto tutto. Ora tutto viene trasportato a ⟦Silithus=Silitus⟧ e dovrebbe arrivare in meno di $2113w giorni. Quando sarà fatto e qualcuno suonerà il gong sull'Altare dello Scarabeo con lo Scettro delle Sabbie Mutevoli, la guerra avrà inizio!", "." },
  ["2e8ce5dcec7b5c7d"] = { "Ho vinto!!", "." },
  ["2e8dce7298f275bf"] = { "Il ⟦Snowfall Graveyard=Cimitero di Nevealta⟧ si trova in cima a una collina nel ⟦Field of Strife=Pian della Discordia⟧, a est del ⟦Winterax Hold=Covo degli Asciafredda⟧.\n\nNessuna delle due parti lo controlla.", "." },
  ["2e8ebc5d22e1734f"] = { "Finalmente. Quel bastardo ha avuto ciò che si meritava.", "." },
  ["2e9474975033913b"] = { "Dov'è l'anziano Gran Monte?", "." },
  ["2e9c74636d389d33"] = { "Il locandiere Kauth può soddisfare le tue esigenze. Lo trovi sul lato ovest del villaggio, in una delle case lunghe.", "." },
  ["2ea299127fb8a03d"] = { "Beh, da quel che sento, la nuova pestilenza ha TUTTO il sapore della vecchia pestilenza, ma nessuna delle sue calorie o dei suoi carboidrati!", "." },
  ["2ea7f4d2d22b50fd"] = { "Mi credevano debole. Haha!!", "." },
  ["2eab6186c5291e28"] = { "Certo che posso aiutarti con l'addestramento. Ho solo il grado di praticante, ma di certo c'è qualcosa che posso mostrarti.", "." },
  ["2ead4d3b5ee85191"] = { "⟦Therum Deepforge=Therum Forgiafonda⟧ è il nano con cui devi parlare. Uno dei migliori fabbri in circolazione, se vuoi la mia opinione. Lo trovi nel cuore del Distretto dei Nani.", "." },
  ["2eafe641cf4c350a"] = { "Sabbie del deserto, sollevatevi e oscurate il sole!", "." },
  ["2ec46bdb752b60d2"] = { "Queste atrocità non morte saranno distrutte!", "." },
  ["2ec6a705438ec035"] = { "Evvai! È ora di far festa!", "." },
  ["2ed1a5c352ce6d57"] = { "I druidi sono molto sensibili alle sofferenze di tutte le creature del mondo. Quando si è scoperto che questi uccelli erano in pericolo, abbiamo organizzato un sistema per salvarli dalla corruzione di Feralas.\n\nUna gnoma di nome ⟦Curgle Cranklehop=Curgle Criccaleva⟧ guida l'impresa: raccoglie le uova e le fa spedire qui, dove me ne prendo cura.\n\nCi farebbe sempre comodo altro aiuto per la nostra causa, {name}. Forse dovresti andare a ⟦Gadgetzan=Meccania⟧ e cercare Curgle.", "." },
  ["2edbf7e0dabd0e70"] = { "%s trasforma gli oggetti che {name} gli ha dato in un totem di purificazione...", "." },
  ["2edf96a3f1a0aa31"] = { "<Demitrian cade in ginocchio.>\n\nHai recuperato l'eterna prigione del mio Maestro!\n\nQuanto a lungo ho atteso questo giorno, e finalmente è arrivato.\n\nDeve essere liberato!", "." },
  ["2ee3cde7bf1cd6d6"] = { "Grazie mille! Mi metto subito al lavoro su un piano di fuga. Nel frattempo, prendi questo!", "." },
  ["2ee3eaf91a7097a6"] = { "Och! Bada bene a cosa ti fai incantare, <ragazzo/ragazza>. Ho fatto incantare il mio boccale perché non versasse una goccia, ma ora non riesco a berci! Che tragedia.\n\nSegui bene il mio consiglio quando vedi Gimble. Lo troverai nella sua bottega, proprio accanto al maestro dei grifoni della ⟦Great Forge=Grande Forgia⟧.", "." },
  ["2ee833636e6dc77c"] = { "Anthion, mi sa che ho perso lo stendardo che hai creato per me.", "." },
  ["2ee997176af6525d"] = { "Vi prego, sacerdotesse, perdonate la nostra intrusione. Non vogliamo fare alcun male qui.", "." },
  ["2eed5f771553d4b2"] = { "Maestro, continua a darmi colpetti!", "." },
  ["2efc0d129c420732"] = { "In base al campione di tossina che ci hai fornito, pensiamo che ti servirà quanto segue: un Accelerante Arcano, cinque Intensificatori Somatici e quattro pezzi di telarunica. Con il Focalizzatore Vitreo al seguito, procurati gli intensificatori dai non morti zombi o ghoul qui nelle ⟦Plaguelands=Terre Infette⟧!\n\nQuando avrai questi oggetti, dovresti poter caricare l'antidoto in quel calderone.", "." },
  ["2efc2c08c9c7460b"] = { "Ultimamente i libri stanno sparendo. Lo storico e i suoi assistenti sono in fermento. Sospettano un'azione criminosa all'interno di Eldre'Thalas.", "." },
})
